-- Permanent per-version/item race disconnection; no admission opening or runtime grants.
-- Original 2..107 bytes and original event4/event6 authority remain unchanged.
-- Unclassified live copied channels fail closed; full authenticated restore/export35,
-- receipt reader dispatch and root grant/registry integration remain separate gates.
CREATE TABLE public.nutrition_race_item_disconnection (
  athlete_id text NOT NULL,
  version_id uuid NOT NULL,
  item_key bytea NOT NULL CHECK(octet_length(item_key)=32),
  item_id text NOT NULL CHECK(length(item_id)>0 AND item_id=btrim(item_id)),
  event_id uuid NOT NULL REFERENCES public.restore_suppression_event(event_id),
  PRIMARY KEY(athlete_id,version_id,item_key),
  FOREIGN KEY(athlete_id,version_id) REFERENCES public.nutrition_plan_version(athlete_id,version_id)
    DEFERRABLE INITIALLY DEFERRED,
  CHECK(item_key=sha256(convert_to(item_id,'UTF8')))
);
REVOKE ALL ON public.nutrition_race_item_disconnection FROM PUBLIC;
ALTER TABLE public.nutrition_race_item_disconnection ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.nutrition_race_item_disconnection FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant ON public.nutrition_race_item_disconnection
 USING(athlete_id=nullif(current_setting('app.athlete_id',true),''))
 WITH CHECK(athlete_id=nullif(current_setting('app.athlete_id',true),''));

-- This exact SQL transformation is a storage draft, NOT a physiological or DTO validator.
-- Caller has validated the V3 codec and bounded the old envelope. No free-text source
-- provenance is assumed: known copied race channels are removed; unclassified copies block admission.
CREATE FUNCTION public.nutrition_redacted_body_v3(b jsonb, ids text[], events uuid[])
RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $sql$
 SELECT (b-'schemaVersion') || jsonb_build_object(
  'schemaVersion',3,
  'items',coalesce((SELECT jsonb_agg(CASE WHEN item->>'id'=ANY(ids) THEN
    (item-'anchor') || jsonb_build_object(
      'anchor',jsonb_build_object('kind','disconnected','entity','race'))
    ELSE item END ORDER BY ord)
    FROM jsonb_array_elements(b->'items') WITH ORDINALITY a(item,ord)),'[]'::jsonb),
  'raceTimingPins',coalesce((SELECT jsonb_agg(pin ORDER BY ord)
    FROM jsonb_array_elements(coalesce(b->'raceTimingPins','[]'::jsonb)) WITH ORDINALITY a(pin,ord)
    WHERE NOT EXISTS(SELECT 1 FROM unnest(events) e WHERE e::text=lower(pin->>'eventId'))),'[]'::jsonb),
  'itemRaceTimingBindings',coalesce((SELECT jsonb_agg(binding ORDER BY ord)
    FROM jsonb_array_elements(coalesce(b->'itemRaceTimingBindings','[]'::jsonb)) WITH ORDINALITY a(binding,ord)
    WHERE NOT (binding->>'itemId'=ANY(ids))),'[]'::jsonb));
$sql$;
REVOKE ALL ON FUNCTION public.nutrition_redacted_body_v3(jsonb,text[],uuid[]) FROM PUBLIC;

-- Single authoritative old4 event authorizes all matching immutable-version copies.
-- Collision/membership checking precedes permanent marker write; no runtime INSERT grant.
CREATE FUNCTION public.verify_nutrition_disconnection() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE body jsonb; target uuid;
BEGIN
 PERFORM public.manual_review_owner();
 PERFORM public.assert_manual_review_global_lock();
 PERFORM public.assert_manual_review_lifecycle_lock(NEW.athlete_id);
 IF current_user<>pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID))
  OR NEW.athlete_id IS DISTINCT FROM nullif(current_setting('app.athlete_id',true),'')
 THEN RAISE EXCEPTION 'NUTRITION_DISCONNECTION_OWNER_REQUIRED'; END IF;
 SELECT e.target_id INTO target FROM public.restore_suppression_event e
  WHERE e.event_id=NEW.event_id AND e.athlete_id=NEW.athlete_id
   AND e.record_version=4 AND e.kind='race_event_deleted';
 IF EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d WHERE d.athlete_id=NEW.athlete_id AND d.version_id=NEW.version_id AND d.item_key=NEW.item_key AND d.item_id IS DISTINCT FROM NEW.item_id) THEN RAISE EXCEPTION 'NUTRITION_ITEM_HASH_COLLISION'; END IF;
 IF target IS NULL THEN RAISE EXCEPTION 'NUTRITION_DISCONNECTION_EVENT_REQUIRED'; END IF;
 SELECT record_json INTO body FROM public.nutrition_plan_version
  WHERE athlete_id=NEW.athlete_id AND version_id=NEW.version_id;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(body->'items') i
  WHERE i->>'id'=NEW.item_id AND i->'anchor'->>'kind'='relative'
   AND i->'anchor'->>'entity'='race' AND lower(i->'anchor'->>'entityId')=target::text)
 THEN RAISE EXCEPTION 'NUTRITION_DISCONNECTION_MEMBERSHIP_REQUIRED'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.verify_nutrition_disconnection() FROM PUBLIC;
CREATE TRIGGER nutrition_disconnect_verify BEFORE INSERT ON public.nutrition_race_item_disconnection
 FOR EACH ROW EXECUTE FUNCTION public.verify_nutrition_disconnection();
CREATE FUNCTION public.guard_nutrition_disconnection_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ BEGIN
 IF TG_OP='DELETE' AND current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID))
  AND OLD.athlete_id IS NOT DISTINCT FROM nullif(current_setting('app.athlete_id',true),'')
  AND EXISTS(SELECT 1 FROM public.tenant_erasure WHERE athlete_id=OLD.athlete_id)
 THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'NUTRITION_DISCONNECTION_IMMUTABLE';
END $$;
REVOKE ALL ON FUNCTION public.guard_nutrition_disconnection_mutation() FROM PUBLIC;
CREATE TRIGGER nutrition_disconnect_immutable BEFORE UPDATE OR DELETE ON public.nutrition_race_item_disconnection
 FOR EACH ROW EXECUTE FUNCTION public.guard_nutrition_disconnection_mutation();
CREATE TRIGGER nutrition_disconnect_no_truncate BEFORE TRUNCATE ON public.nutrition_race_item_disconnection
 FOR EACH STATEMENT EXECUTE FUNCTION public.reject_restore_suppression_event_mutation();

-- Replace ONLY plan-version guard, preserving food/intake/history guards from020.
CREATE FUNCTION public.guard_nutrition_privacy_redaction() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE ids text[]; events uuid[]; expected jsonb;
BEGIN
 PERFORM public.manual_review_owner();
 IF TG_OP='UPDATE' THEN
  PERFORM public.assert_manual_review_global_lock();
  PERFORM public.assert_manual_review_lifecycle_lock(OLD.athlete_id);
 END IF;
 IF current_user<>pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID))
  OR OLD.athlete_id IS DISTINCT FROM nullif(current_setting('app.athlete_id',true),'')
 THEN RAISE EXCEPTION 'IMMUTABLE_NUTRITION_RECORD'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF (to_jsonb(OLD)-'record_json') IS DISTINCT FROM (to_jsonb(NEW)-'record_json')
 THEN RAISE EXCEPTION 'NUTRITION_REDACTION_IDENTITY_CHANGE'; END IF;
 SELECT array_agg(d.item_id ORDER BY d.item_id),array_agg(e.target_id ORDER BY d.item_id)
  INTO ids,events FROM public.nutrition_race_item_disconnection d
  JOIN public.restore_suppression_event e ON e.event_id=d.event_id
  WHERE d.athlete_id=OLD.athlete_id AND d.version_id=OLD.version_id
   AND e.athlete_id=d.athlete_id AND e.record_version=4 AND e.kind='race_event_deleted';
 IF ids IS NULL THEN RAISE EXCEPTION 'NUTRITION_REDACTION_EVENT_REQUIRED'; END IF;
 PERFORM public.assert_nutrition_disconnect_body(OLD.record_json);
 expected:=public.nutrition_redacted_body_v3(OLD.record_json,ids,events);
 IF NEW.record_json IS DISTINCT FROM expected
 THEN RAISE EXCEPTION 'NUTRITION_REDACTION_NOT_EXACT'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.guard_nutrition_privacy_redaction() FROM PUBLIC;
DROP TRIGGER nutrition_plan_version_immutable ON public.nutrition_plan_version;
CREATE TRIGGER nutrition_plan_version_immutable BEFORE UPDATE OR DELETE ON public.nutrition_plan_version
 FOR EACH ROW EXECUTE FUNCTION public.guard_nutrition_privacy_redaction();

-- This validator recognizes only the actual saved-plan channels. It does not treat
-- arbitrary JSON text search as a complete copied-data inventory.
CREATE FUNCTION public.assert_nutrition_disconnect_body(b jsonb) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ BEGIN
 IF jsonb_typeof(b) IS DISTINCT FROM 'object' OR octet_length(b::text)>1048576
  OR (b ? 'schemaVersion' AND b->'schemaVersion' NOT IN ('2'::jsonb,'3'::jsonb))
  OR jsonb_typeof(b->'items') IS DISTINCT FROM 'array'
  OR jsonb_array_length(b->'items')>5000
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(b) k WHERE k<>ALL(ARRAY['schemaVersion','planId','versionId','version','previousVersionId','approvalId','approvedAt','period','timezone','purpose','linkedTrainingPlanVersionId','items','raceTimingPins','itemRaceTimingBindings']))
 THEN RAISE EXCEPTION 'NUTRITION_DISCONNECT_UNSUPPORTED_BODY'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'items') i WHERE jsonb_typeof(i) IS DISTINCT FROM 'object'
   OR jsonb_typeof(i->'id') IS DISTINCT FROM 'string' OR length(i->>'id')=0
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(i) k WHERE k<>ALL(ARRAY['id','planVersionId','category','title','anchor','foods','targets','instructions','evidenceIds','source'])))
  OR (SELECT count(*) FROM jsonb_array_elements(b->'items'))<>(SELECT count(DISTINCT i->>'id') FROM jsonb_array_elements(b->'items') i)
  OR jsonb_typeof(coalesce(b->'raceTimingPins','[]'::jsonb)) IS DISTINCT FROM 'array'
  OR jsonb_typeof(coalesce(b->'itemRaceTimingBindings','[]'::jsonb)) IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'NUTRITION_DISCONNECT_UNSUPPORTED_BODY'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'items') i WHERE jsonb_typeof(i->'anchor') IS DISTINCT FROM 'object'
  OR coalesce(i->'anchor'->>'kind','') NOT IN ('absolute','relative','disconnected')
  OR (i->'anchor'->>'kind'='absolute' AND EXISTS(SELECT 1 FROM jsonb_object_keys(i->'anchor') k WHERE k<>ALL(ARRAY['kind','date','localTime','timezone'])))
  OR (i->'anchor'->>'kind'='relative' AND (coalesce(i->'anchor'->>'entity','') NOT IN ('session','race') OR EXISTS(SELECT 1 FROM jsonb_object_keys(i->'anchor') k WHERE k<>ALL(ARRAY['kind','entity','entityId','point','offsetMinutes']))))
  OR (i->'anchor'->>'kind'='disconnected' AND i->'anchor'<>'{"kind":"disconnected","entity":"race"}'::jsonb))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(b->'raceTimingPins','[]'::jsonb)) p WHERE jsonb_typeof(p) IS DISTINCT FROM 'object'
   OR p->>'namespace' IS DISTINCT FROM 'race-event-revision'
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(p) k WHERE k<>ALL(ARRAY['pinVersion','namespace','eventId','eventRevision','sourceDigestVersion','sourceDigest','localDate','localStartTime','timezone','start','end'])))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(b->'itemRaceTimingBindings','[]'::jsonb)) t WHERE jsonb_typeof(t) IS DISTINCT FROM 'object'
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(t) k WHERE k<>ALL(ARRAY['itemId','binding']))
   OR jsonb_typeof(t->'binding') IS DISTINCT FROM 'object'
   OR coalesce(t->'binding'->>'state','') NOT IN ('captured','legacy_unpinned')
   OR (t->'binding'->>'state'='captured' AND EXISTS(SELECT 1 FROM jsonb_object_keys(t->'binding') k WHERE k<>ALL(ARRAY['state','eventId','eventRevision'])))
   OR (t->'binding'->>'state'='legacy_unpinned' AND EXISTS(SELECT 1 FROM jsonb_object_keys(t->'binding') k WHERE k<>ALL(ARRAY['state','priorNutritionVersionId','priorItemId','priorAnchorDigest']))))
 THEN RAISE EXCEPTION 'NUTRITION_DISCONNECT_UNSUPPORTED_BODY'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'items') i WHERE i->'anchor'->>'entity'='race'
  AND ((i->'anchor'->>'kind'='relative' AND (NOT (i->'anchor' ?& ARRAY['kind','entity','entityId','point','offsetMinutes'])
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(i->'anchor') k WHERE k<>ALL(ARRAY['kind','entity','entityId','point','offsetMinutes']))))
   OR (i->'anchor'->>'kind'='disconnected' AND i->'anchor'<>'{"kind":"disconnected","entity":"race"}'::jsonb)
   OR i->'anchor'->>'kind' NOT IN ('relative','disconnected')))
 THEN RAISE EXCEPTION 'NUTRITION_DISCONNECT_UNSUPPORTED_BODY'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.assert_nutrition_disconnect_body(jsonb) FROM PUBLIC;

-- No retained pin, old legacy race anchor, or unproven disconnected record may be
-- reinserted after suppression. Restore has no unauthenticated INSERT bypass.
CREATE FUNCTION public.guard_nutrition_disconnection_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ BEGIN
 PERFORM public.manual_review_owner();
 IF NEW.athlete_id IS DISTINCT FROM nullif(current_setting('app.athlete_id',true),'') THEN RAISE EXCEPTION 'NUTRITION_DISCONNECT_TENANT_MISMATCH'; END IF;
 PERFORM public.assert_nutrition_disconnect_body(NEW.record_json);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.record_json->'items') i WHERE i->'anchor'->>'kind'='disconnected')
 THEN RAISE EXCEPTION 'NUTRITION_DISCONNECTED_RESTORE_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM public.restore_suppression_event e WHERE e.athlete_id=NEW.athlete_id AND e.record_version=4 AND e.kind='race_event_deleted'
  AND (EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.record_json->'items') i WHERE i->'anchor'->>'entity'='race' AND lower(i->'anchor'->>'entityId')=e.target_id::text)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(NEW.record_json->'raceTimingPins','[]'::jsonb)) p WHERE lower(p->>'eventId')=e.target_id::text)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(NEW.record_json->'itemRaceTimingBindings','[]'::jsonb)) t WHERE lower(t->'binding'->>'eventId')=e.target_id::text)))
 THEN RAISE EXCEPTION 'NUTRITION_SUPPRESSED_RACE_REENTRY'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.guard_nutrition_disconnection_insert() FROM PUBLIC;
CREATE TRIGGER nutrition_disconnect_insert BEFORE INSERT ON public.nutrition_plan_version
 FOR EACH ROW EXECUTE FUNCTION public.guard_nutrition_disconnection_insert();

-- Structural checks are combined with explicit source identity refinements by caller.
CREATE FUNCTION public.nutrition_copy_structural_codec(b jsonb,s jsonb,depth integer DEFAULT 0)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE k text; child jsonb; n numeric; t text; count_matches integer;
BEGIN
 IF depth>64 OR b IS NULL OR s IS NULL THEN RETURN false; END IF;
 IF s ? 'const' AND b IS DISTINCT FROM s->'const' THEN RETURN false; END IF;
 IF s ? 'enum' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'enum') x WHERE x=b) THEN RETURN false; END IF;
 IF s ? 'anyOf' THEN
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'anyOf') x WHERE public.nutrition_copy_structural_codec(b,x,depth+1)) THEN RETURN false; END IF;
 END IF;
 IF s ? 'oneOf' THEN
  SELECT count(*) INTO count_matches FROM jsonb_array_elements(s->'oneOf') x WHERE public.nutrition_copy_structural_codec(b,x,depth+1);
  IF count_matches<>1 THEN RETURN false; END IF;
 END IF;
 t:=s->>'type';
 IF t IS NOT NULL AND NOT (jsonb_typeof(b)=t OR t='integer' AND jsonb_typeof(b)='number') THEN RETURN false; END IF;
 IF jsonb_typeof(b)='object' THEN
  IF s->'additionalProperties'='false'::jsonb AND EXISTS(SELECT 1 FROM jsonb_object_keys(b) key WHERE NOT coalesce(s->'properties','{}'::jsonb) ? key) THEN RETURN false; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(s->'required','[]'::jsonb)) key WHERE NOT b ? key) THEN RETURN false; END IF;
  FOR k,child IN SELECT key,value FROM jsonb_each(b) LOOP
   IF s ? 'propertyNames' AND NOT public.nutrition_copy_structural_codec(to_jsonb(k),s->'propertyNames',depth+1) THEN RETURN false; END IF;
   IF coalesce(s->'properties','{}'::jsonb) ? k THEN
    IF NOT public.nutrition_copy_structural_codec(child,s->'properties'->k,depth+1) THEN RETURN false; END IF;
   ELSIF jsonb_typeof(s->'additionalProperties')='object' THEN
    IF NOT public.nutrition_copy_structural_codec(child,s->'additionalProperties',depth+1) THEN RETURN false; END IF;
   END IF;
  END LOOP;
 ELSIF jsonb_typeof(b)='array' THEN
  IF s ? 'minItems' AND jsonb_array_length(b)<(s->>'minItems')::integer OR s ? 'maxItems' AND jsonb_array_length(b)>(s->>'maxItems')::integer THEN RETURN false; END IF;
  IF s ? 'items' THEN FOR child IN SELECT value FROM jsonb_array_elements(b) LOOP
   IF NOT public.nutrition_copy_structural_codec(child,s->'items',depth+1) THEN RETURN false; END IF;
  END LOOP; END IF;
 ELSIF jsonb_typeof(b)='string' THEN
  t:=b#>>'{}';
  -- JavaScript/Zod counts UTF-16 code units, PostgreSQL length counts Unicode scalars.
  IF s ? 'minLength' OR s ? 'maxLength' THEN
   count_matches:=length(t);
   IF s ? 'maxLength' AND count_matches>(s->>'maxLength')::integer THEN RETURN false; END IF;
   count_matches:=count_matches+(SELECT count(*)::integer FROM generate_series(1,length(t)) p WHERE ascii(substr(t,p,1))>65535);
  END IF;
  IF s ? 'minLength' AND count_matches<(s->>'minLength')::integer OR s ? 'maxLength' AND count_matches>(s->>'maxLength')::integer THEN RETURN false; END IF;
  IF s ? 'pattern' AND t !~ replace(s->>'pattern',E'\\\\',E'\\') THEN RETURN false; END IF;
 ELSIF jsonb_typeof(b)='number' THEN
  n:=(b#>>'{}')::numeric;
  IF s->>'type'='integer' AND n<>trunc(n) THEN RETURN false; END IF;
  IF s ? 'minimum' AND n<(s->>'minimum')::numeric OR s ? 'maximum' AND n>(s->>'maximum')::numeric OR s ? 'exclusiveMinimum' AND n<=(s->>'exclusiveMinimum')::numeric THEN RETURN false; END IF;
 END IF;
 RETURN true;
END $$;

