-- ECMAScript canonical payload encoding, separate from PostgreSQL row encoding.
CREATE FUNCTION public.nutrition_copy_utf16_key(v text) RETURNS bytea
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE out bytea:=''::bytea; n integer; p integer;
BEGIN
 FOR p IN 1..length(v) LOOP
  n:=ascii(substr(v,p,1));
  IF n<=65535 THEN out:=out||decode(lpad(to_hex(n),4,'0'),'hex');
  ELSE n:=n-65536; out:=out||decode(lpad(to_hex(55296+n/1024),4,'0')||lpad(to_hex(56320+n%1024),4,'0'),'hex'); END IF;
 END LOOP;
 RETURN out;
END $$;
CREATE FUNCTION public.nutrition_copy_number_json(v jsonb) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp SET extra_float_digits=3 AS $$
DECLARE f double precision; s text; sign text:=''; digits text; exponent integer:=0; decimal_pos integer; dot integer;
BEGIN
 f:=(v#>>'{}')::double precision;
 IF f=0 THEN RETURN '0'; END IF;
 IF f='Infinity'::double precision OR f='-Infinity'::double precision OR f='NaN'::double precision THEN RAISE EXCEPTION 'NUTRITION_COPY_NUMBER_UNSUPPORTED'; END IF;
 s:=lower(f::text);
 IF left(s,1)='-' THEN sign:='-';s:=substr(s,2); END IF;
 IF strpos(s,'e')>0 THEN exponent:=split_part(s,'e',2)::integer; s:=split_part(s,'e',1); END IF;
 dot:=strpos(s,'.');
 decimal_pos:=CASE WHEN dot=0 THEN length(s) ELSE dot-1 END+exponent;
 digits:=replace(s,'.','');
 WHILE left(digits,1)='0' LOOP digits:=substr(digits,2); decimal_pos:=decimal_pos-1; END LOOP;
 digits:=rtrim(digits,'0');
 IF decimal_pos>21 OR decimal_pos<=-6 THEN
  exponent:=decimal_pos-1;
  RETURN sign||left(digits,1)||CASE WHEN length(digits)>1 THEN '.'||substr(digits,2) ELSE '' END||'e'||CASE WHEN exponent>=0 THEN '+' ELSE '' END||exponent::text;
 END IF;
 IF decimal_pos<=0 THEN RETURN sign||'0.'||repeat('0',-decimal_pos)||digits; END IF;
 IF decimal_pos>=length(digits) THEN RETURN sign||digits||repeat('0',decimal_pos-length(digits)); END IF;
 RETURN sign||left(digits,decimal_pos)||'.'||substr(digits,decimal_pos+1);
END $$;
CREATE FUNCTION public.nutrition_copy_canonical_json(v jsonb,depth integer DEFAULT 0) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE out text;
BEGIN
 IF depth>64 OR v IS NULL THEN RAISE EXCEPTION 'NUTRITION_COPY_CANONICAL_UNSUPPORTED'; END IF;
 CASE jsonb_typeof(v)
 WHEN 'object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||public.nutrition_copy_canonical_json(value,depth+1),',' ORDER BY public.nutrition_copy_utf16_key(key)),'')||'}' INTO out FROM jsonb_each(v);
 WHEN 'array' THEN SELECT '['||coalesce(string_agg(public.nutrition_copy_canonical_json(value,depth+1),',' ORDER BY ord),'')||']' INTO out FROM jsonb_array_elements(v) WITH ORDINALITY a(value,ord);
 WHEN 'number' THEN out:=public.nutrition_copy_number_json(v);
 ELSE out:=v::text;
 END CASE;
 RETURN out;
END $$;

CREATE FUNCTION public.nutrition_copy_candidate_manifest(tenant text,candidate uuid,proposal uuid,payload_digest text,stamp timestamptz,b jsonb)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE h jsonb; w jsonb; r jsonb; versions jsonb:='[]'::jsonb; races jsonb:='[]'::jsonb; item_refs jsonb:='[]'::jsonb; visits integer:=0; k text; keys text[]:='{}'; deps text[]:=ARRAY['activity-head','intake-head','supplementary-execution-head','supplementary-set-head','food-catalog-head','exercise-catalog-head','routine-catalog-head','routine-run-head','routine-occurrence-head','routine-blueprint-head','recovery-action-head','recovery-method-head','check-in-head','session-completion-head','coaching-constraint-head','ai-consent'];
BEGIN
 IF b IS NULL OR octet_length(b::text)>4194304 OR NOT public.nutrition_copy_structural_codec(b,public.nutrition_copy_schema('integratedCandidateV4Schema'))
 THEN RAISE EXCEPTION 'NUTRITION_COPY_UNSUPPORTED_CANDIDATE:%',candidate; END IF;
 IF (b->>'id')::uuid IS DISTINCT FROM candidate OR (b->>'proposalId')::uuid IS DISTINCT FROM proposal OR b->>'digest' IS DISTINCT FROM payload_digest OR (b->>'createdAt')::timestamptz IS DISTINCT FROM stamp
 THEN RAISE EXCEPTION 'NUTRITION_COPY_CANDIDATE_IDENTITY:%',candidate; END IF;
 -- Independent JS-payload canonical digest, NOT SQL jsonb row digest.
 IF encode(sha256(convert_to(public.nutrition_copy_canonical_json(jsonb_build_object('proposalId',b->'proposalId','basis',b->'basis','writes',b->'writes','summary',b->'summary','validation',b->'validation')),'UTF8')),'hex') IS DISTINCT FROM payload_digest
 THEN RAISE EXCEPTION 'NUTRITION_COPY_PAYLOAD_DIGEST:%',candidate; END IF;
 IF jsonb_array_length(b->'basis'->'contextDependencies')<>16 OR EXISTS(SELECT 1 FROM jsonb_array_elements(b->'basis'->'contextDependencies') d WHERE d->>'kind'<>ALL(deps) OR d->>'id' IS DISTINCT FROM 'tenant' OR CASE WHEN d->>'kind'='ai-consent' THEN (d->>'revision') !~ '^[1-9][0-9]*:true$' ELSE (d->>'revision') !~ '^(0|[1-9][0-9]*)$' END) OR (SELECT count(DISTINCT d->>'kind') FROM jsonb_array_elements(b->'basis'->'contextDependencies') d)<>16
 THEN RAISE EXCEPTION 'NUTRITION_COPY_DEPENDENCIES:%',candidate; END IF;
 FOR h IN SELECT value FROM jsonb_array_elements(b->'basis'->'planHeads') LOOP
  visits:=visits+1; IF visits>5000 THEN RAISE EXCEPTION 'NUTRITION_COPY_SOURCE_LIMIT:%',candidate; END IF;
  k:=(h->>'domain')||':'||(h->>'aggregateId')::uuid::text;
  IF k=ANY(keys) THEN RAISE EXCEPTION 'NUTRITION_COPY_DUPLICATE_HEAD:%',candidate; END IF;
  keys:=array_append(keys,k);
  IF h->'head'->>'kind'='exists' THEN
   PERFORM (h->'head'->>'versionId')::uuid;
   IF h->>'domain'='nutrition' THEN versions:=versions||jsonb_build_array(jsonb_build_object('namespace','nutrition-plan-version','planId',(h->>'aggregateId')::uuid,'versionId',(h->'head'->>'versionId')::uuid)); END IF;
  END IF;
 END LOOP;
 keys:='{}';
 FOR w IN SELECT value FROM jsonb_array_elements(b->'writes') LOOP
  k:=(w->>'domain')||':'||(w->>'aggregateId')::uuid::text;
  IF k=ANY(keys) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'basis'->'planHeads') head_row WHERE head_row->>'domain'=w->>'domain' AND (head_row->>'aggregateId')::uuid=(w->>'aggregateId')::uuid) THEN RAISE EXCEPTION 'NUTRITION_COPY_WRITE_HEAD:%',candidate; END IF;
  keys:=array_append(keys,k);
  IF w->>'domain'='nutrition' THEN
   FOR r IN SELECT i->'anchor' FROM jsonb_array_elements(w->'proposed'->'items') i WHERE i->'anchor'->>'kind'='relative' AND i->'anchor'->>'entity'='race' LOOP
    visits:=visits+1; IF visits>5000 THEN RAISE EXCEPTION 'NUTRITION_COPY_SOURCE_LIMIT:%',candidate; END IF;
    IF NOT races @> jsonb_build_array(jsonb_build_object('namespace','race-event','eventId',(r->>'entityId')::uuid)) THEN races:=races||jsonb_build_array(jsonb_build_object('namespace','race-event','eventId',(r->>'entityId')::uuid)); END IF;
   END LOOP;
  ELSIF w->>'domain'='recovery' THEN
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(w->'proposed'->'options') o WHERE (o->>'id')::uuid=(w->>'selectedOptionId')::uuid) THEN RAISE EXCEPTION 'NUTRITION_COPY_RECOVERY_SELECTION:%',candidate; END IF;
   FOR r IN SELECT value FROM jsonb_array_elements(w->'proposed'->'planRefs') WHERE value->>'kind'='nutrition' LOOP
    visits:=visits+1; IF visits>5000 THEN RAISE EXCEPTION 'NUTRITION_COPY_SOURCE_LIMIT:%',candidate; END IF;
    IF NOT versions @> jsonb_build_array(jsonb_build_object('planId',(r->>'aggregateId')::uuid,'versionId',(r->>'headVersionId')::uuid)) THEN RAISE EXCEPTION 'NUTRITION_COPY_RECOVERY_TUPLE:%',candidate; END IF;
   END LOOP;
  ELSIF w->>'domain'='routine_schedule' THEN
   IF w->'proposed'->>'id' IS DISTINCT FROM w->>'aggregateId' THEN RAISE EXCEPTION 'NUTRITION_COPY_SCHEDULE_IDENTITY:%',candidate; END IF;
   FOR r IN SELECT binding->'plannedRef' FROM jsonb_array_elements(w->'occurrences') occurrence CROSS JOIN LATERAL jsonb_array_elements(occurrence->'stepBindings') binding WHERE binding->'plannedRef'->>'domain'='nutrition' LOOP
    visits:=visits+1; IF visits>5000 THEN RAISE EXCEPTION 'NUTRITION_COPY_SOURCE_LIMIT:%',candidate; END IF;
    IF NOT versions @> jsonb_build_array(jsonb_build_object('planId',(r->>'planId')::uuid,'versionId',(r->>'versionId')::uuid)) THEN RAISE EXCEPTION 'NUTRITION_COPY_ROUTINE_TUPLE:%',candidate; END IF;
    IF NOT item_refs @> jsonb_build_array(jsonb_build_object('planId',(r->>'planId')::uuid,'versionId',(r->>'versionId')::uuid,'itemId',r->>'itemId')) THEN item_refs:=item_refs||jsonb_build_array(jsonb_build_object('planId',(r->>'planId')::uuid,'versionId',(r->>'versionId')::uuid,'itemId',r->>'itemId')); END IF;
   END LOOP;
  END IF;
 END LOOP;
 IF jsonb_array_length(versions)+jsonb_array_length(races)+jsonb_array_length(item_refs)>5000 THEN RAISE EXCEPTION 'NUTRITION_COPY_SOURCE_LIMIT:%',candidate; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(b->'writes') write_row WHERE write_row->>'domain'='training')>1 OR (SELECT count(*) FROM jsonb_array_elements(b->'basis'->'planHeads') head_row WHERE head_row->>'domain'='training')>1 THEN RAISE EXCEPTION 'NUTRITION_COPY_TRAINING_HEAD:%',candidate; END IF;
 SELECT coalesce(jsonb_agg(v ORDER BY (v->>'planId')||':'||(v->>'versionId')),'[]'::jsonb) INTO versions FROM jsonb_array_elements(versions) v;
 SELECT coalesce(jsonb_agg(v ORDER BY v->>'eventId'),'[]'::jsonb) INTO races FROM jsonb_array_elements(races) v;
 SELECT coalesce(jsonb_agg(v ORDER BY public.nutrition_copy_utf16_key(public.nutrition_copy_canonical_json(jsonb_build_array(v->'planId',v->'versionId',v->'itemId')))),'[]'::jsonb) INTO item_refs FROM jsonb_array_elements(item_refs) v;
 RETURN jsonb_build_object('manifestVersion',1,'athleteId',tenant,'candidateId',candidate,'payloadDigestVersion','integrated-candidate-v4-canonical-v1','payloadDigest',payload_digest,'nutritionVersions',versions,'races',races,'nutritionItemRefs',item_refs);
END $$;
REVOKE ALL ON FUNCTION public.nutrition_copy_structural_codec(jsonb,jsonb,integer),public.nutrition_copy_schema(text),public.nutrition_copy_utf16_key(text),public.nutrition_copy_number_json(jsonb),public.nutrition_copy_canonical_json(jsonb,integer),public.nutrition_copy_candidate_manifest(text,uuid,uuid,text,timestamptz,jsonb) FROM PUBLIC;

-- A private original-event marker binds the immutable full SQL row fingerprint.
-- payload_digest retains the original JS canonical identity; it is not row_digest.
ALTER TABLE public.integrated_candidate_v4 ALTER COLUMN body DROP NOT NULL;
ALTER TABLE public.integrated_candidate_v4 ADD COLUMN purged_reason text;
ALTER TABLE public.integrated_candidate_v4 ADD CONSTRAINT integrated_candidate_v4_copy_envelope CHECK(((body IS NOT NULL AND purged_reason IS NULL) OR (body IS NULL AND purged_reason='source_deleted')) IS TRUE);
CREATE TABLE public.nutrition_integrated_candidate_disconnection (
 athlete_id text NOT NULL,
 candidate_id uuid NOT NULL,
 event_id uuid NOT NULL REFERENCES public.restore_suppression_event(event_id),
 row_digest_version text NOT NULL CHECK(row_digest_version='postgres-row-jsonb-utc-v1'),
 row_digest text NOT NULL CHECK(row_digest ~ '^[a-f0-9]{64}$'),
 payload_digest_version text NOT NULL CHECK(payload_digest_version='integrated-candidate-v4-canonical-v1'),
 payload_digest text NOT NULL CHECK(payload_digest ~ '^[a-f0-9]{64}$'),
 PRIMARY KEY(athlete_id,candidate_id),
 FOREIGN KEY(athlete_id,candidate_id) REFERENCES public.integrated_candidate_v4(athlete_id,id) DEFERRABLE INITIALLY DEFERRED
);
REVOKE ALL ON public.nutrition_integrated_candidate_disconnection FROM PUBLIC;
ALTER TABLE public.nutrition_integrated_candidate_disconnection ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.nutrition_integrated_candidate_disconnection FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant ON public.nutrition_integrated_candidate_disconnection USING(athlete_id=nullif(current_setting('app.athlete_id',true),'')) WITH CHECK(athlete_id=nullif(current_setting('app.athlete_id',true),''));
CREATE TRIGGER nutrition_integrated_marker_immutable BEFORE UPDATE OR DELETE ON public.nutrition_integrated_candidate_disconnection FOR EACH ROW EXECUTE FUNCTION public.guard_nutrition_disconnection_mutation();
CREATE TRIGGER nutrition_integrated_marker_no_truncate BEFORE TRUNCATE ON public.nutrition_integrated_candidate_disconnection FOR EACH STATEMENT EXECUTE FUNCTION public.reject_restore_suppression_event_mutation();

CREATE FUNCTION public.nutrition_copy_manifest_related(tenant text,candidate uuid,manifest jsonb,target uuid)
RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE source record; item_ref jsonb; count_expected integer; count_matched integer; largest bigint; total bigint; bodies jsonb; related boolean:=false;
BEGIN
 count_expected:=jsonb_array_length(manifest->'nutritionVersions');
 -- Preflight in one MVCC command. No record bodies cross this boundary first.
 WITH requested AS MATERIALIZED (SELECT (ref->>'planId')::uuid plan_id,(ref->>'versionId')::uuid version_id FROM jsonb_array_elements(manifest->'nutritionVersions') ref),
 sizes AS MATERIALIZED (SELECT count(*) matched,coalesce(max(octet_length(v.record_json::text)),0) largest,coalesce(sum(octet_length(jsonb_build_object('athlete_id',v.athlete_id,'plan_id',v.plan_id,'version_id',v.version_id,'record_json',v.record_json)::text)),0)+2*count(*)+2 total FROM requested r JOIN public.nutrition_plan_version v ON v.athlete_id=tenant AND v.plan_id=r.plan_id AND v.version_id=r.version_id)
 SELECT sizes.matched,sizes.largest,sizes.total,CASE WHEN sizes.matched=count_expected AND sizes.largest<=524288 AND sizes.total<=4194304 THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('plan_id',v.plan_id,'version_id',v.version_id,'record_json',v.record_json) ORDER BY v.plan_id,v.version_id),'[]'::jsonb) FROM requested r JOIN public.nutrition_plan_version v ON v.athlete_id=tenant AND v.plan_id=r.plan_id AND v.version_id=r.version_id) ELSE NULL END
 INTO count_matched,largest,total,bodies FROM sizes;
 IF bodies IS NULL THEN RAISE EXCEPTION 'NUTRITION_COPY_SOURCE_UNAVAILABLE:%',candidate; END IF;
 FOR source IN SELECT (value->>'plan_id')::uuid plan_id,(value->>'version_id')::uuid version_id,value->'record_json' record_json FROM jsonb_array_elements(bodies) LOOP
  PERFORM public.assert_nutrition_disconnect_body(source.record_json);
  IF source.record_json->>'planId' IS DISTINCT FROM source.plan_id::text OR source.record_json->>'versionId' IS DISTINCT FROM source.version_id::text THEN RAISE EXCEPTION 'NUTRITION_COPY_SOURCE_IDENTITY:%',candidate; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(source.record_json->'items') i WHERE i->'anchor'->>'kind'='disconnected' AND NOT EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d JOIN public.restore_suppression_event e ON e.event_id=d.event_id AND e.athlete_id=d.athlete_id AND e.record_version=4 AND e.kind='race_event_deleted' WHERE d.athlete_id=tenant AND d.version_id=source.version_id AND d.item_key=sha256(convert_to(i->>'id','UTF8')) AND d.item_id=i->>'id')) THEN RAISE EXCEPTION 'NUTRITION_COPY_SOURCE_MARKER_REQUIRED:%',candidate; END IF;
  FOR item_ref IN SELECT value FROM jsonb_array_elements(manifest->'nutritionItemRefs') WHERE (value->>'planId')::uuid=source.plan_id AND (value->>'versionId')::uuid=source.version_id LOOP
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source.record_json->'items') i WHERE i->>'id'=item_ref->>'itemId') THEN RAISE EXCEPTION 'NUTRITION_COPY_SOURCE_ITEM:%',candidate; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(source.record_json->'items') i WHERE i->'anchor'->>'kind'='relative' AND i->'anchor'->>'entity'='race' AND (i->'anchor'->>'entityId')::uuid=target)
   OR EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d JOIN public.restore_suppression_event e ON e.event_id=d.event_id AND e.athlete_id=d.athlete_id AND e.record_version=4 AND e.kind='race_event_deleted' WHERE d.athlete_id=tenant AND d.version_id=source.version_id AND e.target_id=target)
  THEN related:=true; END IF;
 END LOOP;
 -- UUID equality, not substring matching. Other-tenant/missing source is unknown.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(manifest->'races') r WHERE NOT EXISTS(SELECT 1 FROM public.race_event e WHERE e.athlete_id=tenant AND e.id=(r->>'eventId')::uuid)) THEN RAISE EXCEPTION 'NUTRITION_COPY_RACE_OWNER:%',candidate; END IF;
 RETURN related OR manifest->'races' @> jsonb_build_array(jsonb_build_object('namespace','race-event','eventId',target));
END $$;
CREATE FUNCTION public.verify_nutrition_integrated_marker() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp SET timezone='UTC' SET datestyle='ISO,YMD' AS $$
DECLARE c public.integrated_candidate_v4%ROWTYPE; target uuid; manifest jsonb;
BEGIN
 PERFORM public.manual_review_owner(); PERFORM public.assert_manual_review_global_lock(); PERFORM public.assert_manual_review_lifecycle_lock(NEW.athlete_id);
 IF current_user<>pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID)) OR NEW.athlete_id IS DISTINCT FROM nullif(current_setting('app.athlete_id',true),'') THEN RAISE EXCEPTION 'NUTRITION_COPY_MARKER_OWNER_REQUIRED'; END IF;
 SELECT e.target_id INTO target FROM public.restore_suppression_event e WHERE e.event_id=NEW.event_id AND e.athlete_id=NEW.athlete_id AND e.record_version=4 AND e.kind='race_event_deleted';
 SELECT * INTO c FROM public.integrated_candidate_v4 WHERE athlete_id=NEW.athlete_id AND id=NEW.candidate_id FOR UPDATE;
 IF target IS NULL OR c.body IS NULL OR c.digest IS DISTINCT FROM NEW.payload_digest OR encode(sha256(convert_to(to_jsonb(c)::text,'UTF8')),'hex') IS DISTINCT FROM NEW.row_digest THEN RAISE EXCEPTION 'NUTRITION_COPY_MARKER_AUTHORITY'; END IF;
 manifest:=public.nutrition_copy_candidate_manifest(c.athlete_id,c.id,c.proposal_id,c.digest,c.created_at,c.body);
 IF NOT public.nutrition_copy_manifest_related(c.athlete_id,c.id,manifest,target) THEN RAISE EXCEPTION 'NUTRITION_COPY_MARKER_MEMBERSHIP'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER nutrition_integrated_marker_verify BEFORE INSERT ON public.nutrition_integrated_candidate_disconnection FOR EACH ROW EXECUTE FUNCTION public.verify_nutrition_integrated_marker();
CREATE FUNCTION public.guard_nutrition_integrated_redaction() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp SET timezone='UTC' SET datestyle='ISO,YMD' AS $$ BEGIN
 PERFORM public.manual_review_owner();
 IF current_user<>pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID)) OR OLD.athlete_id IS DISTINCT FROM nullif(current_setting('app.athlete_id',true),'') THEN RAISE EXCEPTION 'IMMUTABLE_INTEGRATED_APPROVAL_RECORD'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 PERFORM public.assert_manual_review_global_lock(); PERFORM public.assert_manual_review_lifecycle_lock(OLD.athlete_id);
 IF OLD.body IS NULL OR NEW.body IS NOT NULL OR NEW.purged_reason IS DISTINCT FROM 'source_deleted' OR (to_jsonb(OLD)-'body'-'purged_reason') IS DISTINCT FROM (to_jsonb(NEW)-'body'-'purged_reason') OR NOT EXISTS(SELECT 1 FROM public.nutrition_integrated_candidate_disconnection m JOIN public.restore_suppression_event e ON e.event_id=m.event_id AND e.athlete_id=m.athlete_id AND e.record_version=4 AND e.kind='race_event_deleted' WHERE m.athlete_id=OLD.athlete_id AND m.candidate_id=OLD.id AND m.payload_digest=OLD.digest AND m.row_digest=encode(sha256(convert_to(to_jsonb(OLD)::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'NUTRITION_COPY_REDACTION_NOT_EXACT'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER integrated_candidate_v4_immutable ON public.integrated_candidate_v4;
CREATE TRIGGER integrated_candidate_v4_immutable BEFORE UPDATE OR DELETE ON public.integrated_candidate_v4 FOR EACH ROW EXECUTE FUNCTION public.guard_nutrition_integrated_redaction();

CREATE FUNCTION public.assert_nutrition_unrelated_training_copies(tenant text) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE d public.coaching_decision%ROWTYPE; p public.coaching_proposal%ROWTYPE; c public.coaching_candidate%ROWTYPE; r public.coaching_run%ROWTYPE; b jsonb; payload jsonb;
BEGIN
 -- Known running-core V1 produces no structured nutrition/race sources. Its
 -- user/model prose is not a typed source ownership claim or a deletion selector.
 FOR d IN SELECT * FROM public.coaching_decision WHERE athlete_id=tenant ORDER BY id LOOP
  IF d.body IS NULL THEN CONTINUE; END IF;
  SELECT * INTO r FROM public.coaching_run WHERE athlete_id=tenant AND id=d.run_id;
  b:=d.body->'basis';
  IF NOT FOUND OR NOT public.nutrition_copy_structural_codec(d.body,public.nutrition_copy_schema('trainingDecisionV1Schema')) OR d.body->>'id' IS DISTINCT FROM d.id::text OR d.body->>'runId' IS DISTINCT FROM d.run_id::text OR (d.body->>'createdAt')::timestamptz IS DISTINCT FROM d.created_at OR b IS DISTINCT FROM r.basis OR b->>'athleteId' IS DISTINCT FROM tenant OR b->'dependencies'->>'athleteId' IS DISTINCT FROM tenant OR b->>'threadId' IS DISTINCT FROM r.thread_id::text OR b->>'evidenceSnapshotId' IS DISTINCT FROM r.evidence_snapshot_id::text OR (b->>'conversationRevision')::integer IS DISTINCT FROM r.conversation_revision OR b->'dependencies'->'trainingPlan'->>'kind' IS DISTINCT FROM 'exists' OR b->'dependencies'->'trainingPlan'->>'versionId' IS DISTINCT FROM b->>'planVersionId' OR b->'dependencies'->'aiConsent'->>'kind' IS DISTINCT FROM 'exists' OR b->'dependencies'->'aiConsent'->'granted' IS DISTINCT FROM 'true'::jsonb
  THEN RAISE EXCEPTION 'NUTRITION_COPY_UNSUPPORTED_DECISION:%',d.id; END IF;
  IF b->'retrieval'->>'kind'='resource-access-v1' AND (b->'retrieval'->'manifest'->>'athleteId' IS DISTINCT FROM tenant OR b->'retrieval'->'manifest'->'aiConsentGranted' IS DISTINCT FROM 'true'::jsonb) THEN RAISE EXCEPTION 'NUTRITION_COPY_UNSUPPORTED_DECISION:%',d.id; END IF;
 END LOOP;
 FOR p IN SELECT * FROM public.coaching_proposal WHERE athlete_id=tenant ORDER BY id LOOP
  IF p.body IS NULL THEN CONTINUE; END IF;
  SELECT * INTO d FROM public.coaching_decision WHERE athlete_id=tenant AND id=p.decision_id;
  IF NOT FOUND OR NOT public.nutrition_copy_structural_codec(p.body,public.nutrition_copy_schema('trainingProposalV1Schema')) OR p.body->>'id' IS DISTINCT FROM p.id::text OR p.body->>'decisionId' IS DISTINCT FROM p.decision_id::text OR p.body->>'runId' IS DISTINCT FROM d.run_id::text OR (p.body->>'createdAt')::timestamptz IS DISTINCT FROM p.created_at OR (SELECT count(*) FROM jsonb_array_elements(p.body->'candidateIds'))<>(SELECT count(DISTINCT value) FROM jsonb_array_elements(p.body->'candidateIds')) THEN RAISE EXCEPTION 'NUTRITION_COPY_UNSUPPORTED_PROPOSAL:%',p.id; END IF;
 END LOOP;
 FOR c IN SELECT * FROM public.coaching_candidate WHERE athlete_id=tenant ORDER BY id LOOP
  IF c.body IS NULL THEN CONTINUE; END IF;
  SELECT * INTO d FROM public.coaching_decision WHERE athlete_id=tenant AND id=c.decision_id;
  IF NOT FOUND OR d.body IS NULL THEN RAISE EXCEPTION 'NUTRITION_COPY_UNSUPPORTED_CHAIN:%',c.id; END IF;
  SELECT * INTO p FROM public.coaching_proposal WHERE athlete_id=tenant AND id=c.proposal_id AND decision_id=c.decision_id;
  IF NOT FOUND OR p.body IS NULL OR NOT public.nutrition_copy_structural_codec(c.body,public.nutrition_copy_schema('trainingCandidateV1Schema')) OR c.body->>'id' IS DISTINCT FROM c.id::text OR c.body->>'decisionId' IS DISTINCT FROM c.decision_id::text OR c.body->>'proposalId' IS DISTINCT FROM c.proposal_id::text OR c.body->>'runId' IS DISTINCT FROM d.run_id::text OR (c.body->>'parentCandidateId')::uuid IS DISTINCT FROM c.parent_candidate_id OR (c.body->>'createdAt')::timestamptz IS DISTINCT FROM c.created_at OR c.body->>'digest' IS DISTINCT FROM c.digest OR c.body->'basis' IS DISTINCT FROM d.body->'basis' OR NOT p.body->'candidateIds' @> jsonb_build_array(to_jsonb(c.id)) OR c.body->'before'->>'id' IS DISTINCT FROM c.body->'basis'->>'planVersionId' THEN RAISE EXCEPTION 'NUTRITION_COPY_UNSUPPORTED_CANDIDATE_CHAIN:%',c.id; END IF;
  payload:=jsonb_build_object('schemaVersion',1,'branch',jsonb_build_object('runId',c.body->'runId','decisionId',c.body->'decisionId','proposalId',c.body->'proposalId','candidateId',c.body->'id')||CASE WHEN c.parent_candidate_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('parentCandidateId',c.body->'parentCandidateId') END,'draft',c.body-ARRAY['id','proposalId','decisionId','runId','parentCandidateId','createdAt','digest']);
  IF encode(sha256(convert_to(public.nutrition_copy_canonical_json(payload),'UTF8')),'hex') IS DISTINCT FROM c.digest THEN RAISE EXCEPTION 'NUTRITION_COPY_TRAINING_PAYLOAD_DIGEST:%',c.id; END IF;
 END LOOP;
END $$;
CREATE FUNCTION public.assert_nutrition_minimal_integrated_approvals(tenant text) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE a public.integrated_approval_v4%ROWTYPE; c public.integrated_candidate_v4%ROWTYPE;
BEGIN
 FOR a IN SELECT * FROM public.integrated_approval_v4 WHERE athlete_id=tenant ORDER BY approval_id LOOP
  SELECT * INTO c FROM public.integrated_candidate_v4 WHERE athlete_id=tenant AND id=a.candidate_id;
  IF NOT FOUND OR a.proposal_id IS DISTINCT FROM c.proposal_id OR a.proposal_digest IS DISTINCT FROM c.digest OR NOT public.nutrition_copy_structural_codec(a.result_json,public.nutrition_copy_schema('integratedApprovalResultV4Schema')) OR (a.result_json->>'approvalId')::uuid IS DISTINCT FROM a.approval_id OR (a.result_json->>'candidateId')::uuid IS DISTINCT FROM a.candidate_id OR (a.result_json->>'approvedAt')::timestamptz IS DISTINCT FROM a.approved_at OR (SELECT count(*) FROM jsonb_array_elements(a.result_json->'versions'))<>(SELECT count(DISTINCT (v->>'domain')||':'||(v->>'aggregateId')::uuid::text) FROM jsonb_array_elements(a.result_json->'versions') v) OR (SELECT count(*) FROM jsonb_array_elements_text(a.result_json->'occurrenceIds'))<>(SELECT count(DISTINCT v::uuid) FROM jsonb_array_elements_text(a.result_json->'occurrenceIds') v)
  THEN RAISE EXCEPTION 'NUTRITION_COPY_UNSUPPORTED_APPROVAL:%',a.approval_id; END IF;
 END LOOP;
END $$;
CREATE FUNCTION public.apply_nutrition_copied_channel_disconnection(event uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' SET datestyle='ISO,YMD' AS $$
DECLARE tenant text:=nullif(current_setting('app.athlete_id',true),''); e public.restore_suppression_event%ROWTYPE; c public.integrated_candidate_v4%ROWTYPE; manifest jsonb;
BEGIN
 PERFORM public.manual_review_owner(); PERFORM public.assert_manual_review_global_lock(); PERFORM public.assert_manual_review_lifecycle_lock(tenant);
 SELECT * INTO e FROM public.restore_suppression_event WHERE event_id=$1 AND athlete_id=tenant AND record_version=4 AND kind='race_event_deleted';
 IF NOT FOUND THEN RAISE EXCEPTION 'NUTRITION_COPY_EVENT_REQUIRED'; END IF;
 PERFORM public.assert_nutrition_unrelated_training_copies(tenant);
 PERFORM public.assert_nutrition_minimal_integrated_approvals(tenant);
 FOR c IN SELECT * FROM public.integrated_candidate_v4 WHERE athlete_id=tenant ORDER BY id FOR UPDATE LOOP
  IF c.body IS NULL THEN
   IF NOT EXISTS(SELECT 1 FROM public.nutrition_integrated_candidate_disconnection m JOIN public.restore_suppression_event x ON x.event_id=m.event_id AND x.athlete_id=m.athlete_id AND x.record_version=4 AND x.kind='race_event_deleted' WHERE m.athlete_id=tenant AND m.candidate_id=c.id AND m.payload_digest=c.digest) THEN RAISE EXCEPTION 'NUTRITION_COPY_PURGED_MARKER_REQUIRED:%',c.id; END IF;
   CONTINUE;
  END IF;
  manifest:=public.nutrition_copy_candidate_manifest(tenant,c.id,c.proposal_id,c.digest,c.created_at,c.body);
  IF NOT public.nutrition_copy_manifest_related(tenant,c.id,manifest,e.target_id) THEN CONTINUE; END IF;
  INSERT INTO public.nutrition_integrated_candidate_disconnection(athlete_id,candidate_id,event_id,row_digest_version,row_digest,payload_digest_version,payload_digest) VALUES(tenant,c.id,e.event_id,'postgres-row-jsonb-utc-v1',encode(sha256(convert_to(to_jsonb(c)::text,'UTF8')),'hex'),'integrated-candidate-v4-canonical-v1',c.digest);
  UPDATE public.integrated_candidate_v4 SET body=NULL,purged_reason='source_deleted' WHERE athlete_id=tenant AND id=c.id;
 END LOOP;
END $$;
CREATE FUNCTION public.guard_nutrition_integrated_copy_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE manifest jsonb; e record; tenant text:=nullif(current_setting('app.athlete_id',true),'');
BEGIN
 PERFORM public.manual_review_owner();
 IF NEW.athlete_id IS DISTINCT FROM tenant THEN RAISE EXCEPTION 'NUTRITION_COPY_TENANT_MISMATCH'; END IF;
 IF NEW.body IS NULL THEN RAISE EXCEPTION 'NUTRITION_COPY_AUTHENTICATED_RESTORE_REQUIRED'; END IF;
 manifest:=public.nutrition_copy_candidate_manifest(tenant,NEW.id,NEW.proposal_id,NEW.digest,NEW.created_at,NEW.body);
 FOR e IN SELECT target_id FROM public.restore_suppression_event WHERE athlete_id=tenant AND record_version=4 AND kind='race_event_deleted' LOOP
  IF public.nutrition_copy_manifest_related(tenant,NEW.id,manifest,e.target_id) THEN RAISE EXCEPTION 'NUTRITION_COPY_SUPPRESSED_SOURCE_REENTRY'; END IF;
 END LOOP;
 RETURN NEW;
END $$;
CREATE TRIGGER nutrition_integrated_copy_insert BEFORE INSERT ON public.integrated_candidate_v4 FOR EACH ROW EXECUTE FUNCTION public.guard_nutrition_integrated_copy_insert();
REVOKE ALL ON FUNCTION public.nutrition_copy_manifest_related(text,uuid,jsonb,uuid),public.verify_nutrition_integrated_marker(),public.guard_nutrition_integrated_redaction(),public.assert_nutrition_unrelated_training_copies(text),public.assert_nutrition_minimal_integrated_approvals(text),public.apply_nutrition_copied_channel_disconnection(uuid),public.guard_nutrition_integrated_copy_insert() FROM PUBLIC;

CREATE FUNCTION public.assert_nutrition_save_copy_request(request jsonb,result jsonb) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE command jsonb; intent jsonb; projected jsonb; expected jsonb; previous text; current_id text;
BEGIN
 IF request->>'operation' IS DISTINCT FROM 'nutrition_plan_save' THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
 IF NOT request ? 'intentSchemaVersion' THEN
  command:=request-'operation';
  IF NOT public.nutrition_copy_structural_codec(command,public.nutrition_copy_schema('saveNutritionPlanVersionRequestSchema')) THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
 ELSIF request->'intentSchemaVersion'='2'::jsonb THEN
  command:=request-ARRAY['operation','intentSchemaVersion','expectedRaceHeads'];
  intent:=jsonb_build_object('schemaVersion',2,'command',command,'expectedRaceHeads',request->'expectedRaceHeads');
  IF NOT public.nutrition_copy_structural_codec(intent,public.nutrition_copy_schema('saveNutritionPlanV2IntentSchema')) OR octet_length(public.nutrition_copy_canonical_json(intent))>524288 THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
  previous:=NULL;
  FOR expected IN SELECT value FROM jsonb_array_elements(request->'expectedRaceHeads') LOOP
   current_id:=(expected->>'eventId')::uuid::text;
   IF expected->>'eventId' IS DISTINCT FROM current_id OR previous IS NOT NULL AND previous>=current_id THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
   previous:=current_id;
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(command->'draft'->'items') i WHERE i->'anchor'->>'kind'='relative' AND i->'anchor'->>'entity'='race' AND (i->'anchor'->>'entityId')::uuid=current_id::uuid) THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(command->'draft'->'items') i WHERE i->'anchor'->>'kind'='relative' AND i->'anchor'->>'entity'='race' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(request->'expectedRaceHeads') e WHERE (e->>'eventId')::uuid=(i->'anchor'->>'entityId')::uuid)) THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
 ELSE
  -- V3 writer/reconnect needs an authentic owned-prior marker protocol. Never
  -- infer that authority from a flat client confirmed/reconnect field.
  RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_INTENT_VERSION_UNSUPPORTED';
 END IF;
 PERFORM public.assert_nutrition_disconnect_body(result);
 projected:=(result-ARRAY['schemaVersion','planId','versionId','version','previousVersionId','approvalId','approvedAt','raceTimingPins','itemRaceTimingBindings'])||jsonb_build_object('items',(SELECT coalesce(jsonb_agg(i-'planVersionId' ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(result->'items') WITH ORDINALITY a(i,ord)));
 IF command->'draft' IS DISTINCT FROM projected OR command->'confirmed' IS DISTINCT FROM 'true'::jsonb OR command->>'kind'='update' AND ((command->>'planId')::uuid IS DISTINCT FROM (result->>'planId')::uuid OR (command->>'expectedHeadVersionId')::uuid IS DISTINCT FROM (result->>'previousVersionId')::uuid) THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.assert_nutrition_save_copy_request(jsonb,jsonb) FROM PUBLIC;

CREATE FUNCTION public.apply_nutrition_race_disconnection(event uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE e public.restore_suppression_event%ROWTYPE; record_row public.nutrition_plan_version%ROWTYPE;
 tenant text:=nullif(current_setting('app.athlete_id',true),''); item jsonb; ids text[]; events uuid[];
 receipt public.command_receipt%ROWTYPE; saved public.nutrition_plan_version%ROWTYPE;
BEGIN
 PERFORM public.manual_review_owner();
 PERFORM public.assert_manual_review_global_lock();
 PERFORM public.assert_manual_review_lifecycle_lock(tenant);
 PERFORM pg_advisory_xact_lock(hashtextextended(tenant,0));
 SELECT * INTO e FROM public.restore_suppression_event x WHERE x.event_id=$1 AND x.athlete_id=tenant AND x.record_version=4 AND x.kind='race_event_deleted';
 IF NOT FOUND THEN RAISE EXCEPTION 'NUTRITION_DISCONNECTION_EVENT_REQUIRED'; END IF;
 -- A pin without its source item is not a validated V2/V3 record. Do not
 -- silently drop unrelated malformed copied data or leave an orphan copied pin.
 IF EXISTS(SELECT 1 FROM public.nutrition_plan_version v WHERE v.athlete_id=tenant
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(v.record_json->'raceTimingPins','[]'::jsonb)) p WHERE lower(p->>'eventId')=e.target_id::text)
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v.record_json->'items') i WHERE i->'anchor'->>'entity'='race' AND lower(i->'anchor'->>'entityId')=e.target_id::text)
  AND NOT EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d WHERE d.athlete_id=tenant AND d.version_id=v.version_id AND d.event_id=e.event_id))
 THEN RAISE EXCEPTION 'NUTRITION_DISCONNECT_UNSUPPORTED_BODY'; END IF;
 -- Exact copied-channel inventory runs even when no saved nutrition version exists.
 PERFORM public.apply_nutrition_copied_channel_disconnection(e.event_id);
 FOR record_row IN SELECT * FROM public.nutrition_plan_version v WHERE v.athlete_id=tenant AND
  (EXISTS(SELECT 1 FROM jsonb_array_elements(v.record_json->'items') i WHERE i->'anchor'->>'entity'='race' AND lower(i->'anchor'->>'entityId')=e.target_id::text)
   OR EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d WHERE d.athlete_id=tenant AND d.version_id=v.version_id AND d.event_id=e.event_id)) ORDER BY v.version_id FOR UPDATE
 LOOP
  PERFORM public.assert_nutrition_disconnect_body(record_row.record_json);
  -- UPDATE would invalidate the original copied-row fingerprint; suppress FIRST.
  -- Owner replay never mints6. Existing106 requires the original exact6 tail.
  PERFORM public.suppress_manual_review_source('nutrition-plan-version',record_row.plan_id::text,record_row.version_id::text);
  FOR item IN SELECT i FROM jsonb_array_elements(record_row.record_json->'items') i WHERE i->'anchor'->>'entity'='race' AND lower(i->'anchor'->>'entityId')=e.target_id::text LOOP
   INSERT INTO public.nutrition_race_item_disconnection(athlete_id,version_id,item_key,item_id,event_id)
    VALUES(tenant,record_row.version_id,sha256(convert_to(item->>'id','UTF8')),item->>'id',e.event_id)
    ON CONFLICT(athlete_id,version_id,item_key) DO NOTHING;
   IF NOT EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d WHERE d.athlete_id=tenant AND d.version_id=record_row.version_id AND d.item_key=sha256(convert_to(item->>'id','UTF8')) AND d.item_id=item->>'id' AND d.event_id=e.event_id)
   THEN RAISE EXCEPTION 'NUTRITION_DISCONNECTION_MARKER_CONFLICT'; END IF;
  END LOOP;
  SELECT array_agg(d.item_id ORDER BY d.item_id),array_agg(x.target_id ORDER BY d.item_id) INTO ids,events
   FROM public.nutrition_race_item_disconnection d JOIN public.restore_suppression_event x ON x.event_id=d.event_id
   WHERE d.athlete_id=tenant AND d.version_id=record_row.version_id AND x.athlete_id=tenant AND x.record_version=4 AND x.kind='race_event_deleted';
  UPDATE public.nutrition_plan_version SET record_json=public.nutrition_redacted_body_v3(record_row.record_json,ids,events)
   WHERE athlete_id=tenant AND version_id=record_row.version_id;
 END LOOP;
 -- Exact registered receipt family only. Unknown matching save receipts fail
 -- closed, never discard approval/user intent or use JS serialization as SQL hash.
 FOR receipt IN SELECT * FROM public.command_receipt c WHERE c.athlete_id=tenant AND c.request->>'operation'='nutrition_plan_save' ORDER BY c.idempotency_key FOR UPDATE LOOP
  PERFORM public.assert_nutrition_save_copy_request(receipt.request,receipt.result);
  SELECT * INTO saved FROM public.nutrition_plan_version v WHERE v.athlete_id=tenant
   AND v.version_id::text=lower(receipt.result->>'versionId') AND v.plan_id::text=lower(receipt.result->>'planId');
  IF NOT FOUND THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d WHERE d.athlete_id=tenant AND d.version_id=saved.version_id) THEN CONTINUE; END IF;
  IF receipt.result->>'approvalId' IS DISTINCT FROM saved.approval_id::text
   OR receipt.result->>'version' IS DISTINCT FROM saved.version::text
   OR public.nutrition_redacted_body_v3(receipt.result,ARRAY(SELECT d.item_id FROM public.nutrition_race_item_disconnection d WHERE d.athlete_id=tenant AND d.version_id=saved.version_id ORDER BY d.item_id),
     ARRAY(SELECT x.target_id FROM public.nutrition_race_item_disconnection d JOIN public.restore_suppression_event x ON x.event_id=d.event_id WHERE d.athlete_id=tenant AND d.version_id=saved.version_id ORDER BY d.item_id)) IS DISTINCT FROM saved.record_json
  THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
  UPDATE public.command_receipt SET
   request=jsonb_build_object('receiptVersion',2,'digestVersion','postgres-jsonb-sha256-v1','requestDigest',encode(sha256(convert_to(receipt.request::text,'UTF8')),'hex')),
   result=jsonb_build_object('receiptVersion',2,'outcome','committed','kind','nutrition_plan','planId',saved.plan_id,'versionId',saved.version_id,'version',saved.version,'approvalId',saved.approval_id)
   WHERE athlete_id=tenant AND idempotency_key=receipt.idempotency_key;
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.apply_nutrition_race_disconnection(uuid) FROM PUBLIC;

-- Revoke inherited ACLs on ALL renamed wrappers: new runtime grants are Root-owned.
ALTER FUNCTION public.delete_race_entity(text,uuid,integer) RENAME TO delete_race_entity_before_nutrition_disconnect;
ALTER FUNCTION public.replay_race_deletion_exact(text,text,uuid,uuid,timestamptz,integer,integer) RENAME TO replay_race_deletion_exact_before_nutrition_disconnect;
ALTER FUNCTION public.erase_account(text) RENAME TO erase_account_before_nutrition_disconnect;
DO $$ DECLARE sig text; r text; BEGIN
 FOREACH sig IN ARRAY ARRAY['public.delete_race_entity_before_nutrition_disconnect(text,uuid,integer)',
 'public.replay_race_deletion_exact_before_nutrition_disconnect(text,text,uuid,uuid,timestamptz,integer,integer)',
 'public.erase_account_before_nutrition_disconnect(text)'] LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',sig);
  FOR r IN SELECT DISTINCT pg_get_userbyid(a.grantee) FROM pg_proc p,LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=sig::regprocedure AND a.grantee<>0 AND a.grantee<>p.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',sig,r);
  END LOOP;
 END LOOP;
END $$;
CREATE FUNCTION public.delete_race_entity(kind text,target uuid,expected_revision integer) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE result jsonb; event uuid; tenant text:=nullif(current_setting('app.athlete_id',true),''); BEGIN
 PERFORM public.manual_review_owner();
 PERFORM pg_advisory_xact_lock_shared(77210,1);
 result:=public.delete_race_entity_before_nutrition_disconnect($1,$2,$3);
 IF $1='race-event' THEN
  SELECT e.event_id INTO event FROM public.restore_suppression_event e WHERE e.athlete_id=tenant AND e.record_version=4 AND e.kind='race_event_deleted' AND e.target_id=$2;
  PERFORM public.apply_nutrition_race_disconnection(event);
 END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.delete_race_entity(text,uuid,integer) FROM PUBLIC;
CREATE FUNCTION public.replay_race_deletion_exact(athlete text,kind text,target uuid,event uuid,stamp timestamptz,prior_revision integer,deleted_revision integer) RETURNS text
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ DECLARE result text; BEGIN
 -- INVOKER106 authenticates exact owner/event/receipt BEFORE this posthook.
 result:=public.replay_race_deletion_exact_before_nutrition_disconnect($1,$2,$3,$4,$5,$6,$7);
 IF $2='race_event_deleted' THEN PERFORM public.apply_nutrition_race_disconnection($4); END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.replay_race_deletion_exact(text,text,uuid,uuid,timestamptz,integer,integer) FROM PUBLIC;
CREATE FUNCTION public.erase_account(text) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE stamp timestamptz; BEGIN
 -- FK is deferred: original erase emits its authentic event and removes nutrition
 -- parents before marker cleanup. Statement atomicity keeps no dangling marker.
 stamp:=public.erase_account_before_nutrition_disconnect($1);
 DELETE FROM public.nutrition_race_item_disconnection WHERE athlete_id=$1;
 DELETE FROM public.nutrition_integrated_candidate_disconnection WHERE athlete_id=$1;
 RETURN stamp;
END $$;
REVOKE ALL ON FUNCTION public.erase_account(text) FROM PUBLIC;

-- The saved-body guard alone cannot stop a restored receipt returning an old
-- copied pin. Protect the registered receipt family at INSERT/UPDATE as well.
CREATE FUNCTION public.guard_nutrition_save_receipt_copy() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE tenant text:=nullif(current_setting('app.athlete_id',true),''); b jsonb;
BEGIN
 PERFORM public.manual_review_owner();
 IF NEW.athlete_id IS DISTINCT FROM tenant THEN RAISE EXCEPTION 'NUTRITION_DISCONNECT_TENANT_MISMATCH'; END IF;
 IF NEW.idempotency_key NOT LIKE 'nutrition-plan:%' AND NEW.request->>'operation' IS DISTINCT FROM 'nutrition_plan_save' THEN RETURN NEW; END IF;
 IF NEW.request->>'receiptVersion'='2' THEN
  IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_RESTORE_REQUIRED'; END IF;
  IF OLD.request->>'receiptVersion'='2' THEN
   IF to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW) THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_IMMUTABLE'; END IF;
   RETURN NEW;
  END IF;
  IF OLD.request->>'operation' IS DISTINCT FROM 'nutrition_plan_save'
   OR NEW.athlete_id IS DISTINCT FROM OLD.athlete_id OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
   OR NEW.request IS DISTINCT FROM jsonb_build_object('receiptVersion',2,'digestVersion','postgres-jsonb-sha256-v1','requestDigest',encode(sha256(convert_to(OLD.request::text,'UTF8')),'hex'))
   OR NOT EXISTS(SELECT 1 FROM public.nutrition_plan_version v WHERE v.athlete_id=tenant
    AND v.version_id::text=lower(OLD.result->>'versionId') AND v.plan_id::text=lower(OLD.result->>'planId')
    AND EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d WHERE d.athlete_id=tenant AND d.version_id=v.version_id)
    AND NEW.result=jsonb_build_object('receiptVersion',2,'outcome','committed','kind','nutrition_plan','planId',v.plan_id,'versionId',v.version_id,'version',v.version,'approvalId',v.approval_id))
  THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.request->>'operation' IS DISTINCT FROM 'nutrition_plan_save' THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
 PERFORM public.assert_nutrition_save_copy_request(NEW.request,NEW.result);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.result->'items') i WHERE i->'anchor'->>'kind'='disconnected')
  OR EXISTS(SELECT 1 FROM public.nutrition_race_item_disconnection d WHERE d.athlete_id=tenant AND d.version_id::text=lower(NEW.result->>'versionId'))
 THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_RESTORE_REQUIRED'; END IF;
 IF NEW.request ? 'expectedRaceHeads' AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.request->'expectedRaceHeads') h JOIN public.restore_suppression_event e ON e.athlete_id=tenant AND e.record_version=4 AND e.kind='race_event_deleted' AND e.target_id=(h->>'eventId')::uuid) THEN RAISE EXCEPTION 'NUTRITION_SUPPRESSED_RECEIPT_REENTRY'; END IF;
 FOREACH b IN ARRAY ARRAY[NEW.result,NEW.request->'draft'] LOOP
  IF jsonb_typeof(b->'items') IS DISTINCT FROM 'array'
   OR jsonb_typeof(coalesce(b->'raceTimingPins','[]'::jsonb)) IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'NUTRITION_SAVE_RECEIPT_CODEC_REQUIRED'; END IF;
  IF EXISTS(SELECT 1 FROM public.restore_suppression_event e WHERE e.athlete_id=tenant AND e.record_version=4 AND e.kind='race_event_deleted'
   AND (EXISTS(SELECT 1 FROM jsonb_array_elements(b->'items') i WHERE i->'anchor'->>'entity'='race' AND lower(i->'anchor'->>'entityId')=e.target_id::text)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(b->'raceTimingPins','[]'::jsonb)) p WHERE lower(p->>'eventId')=e.target_id::text)))
  THEN RAISE EXCEPTION 'NUTRITION_SUPPRESSED_RECEIPT_REENTRY'; END IF;
 END LOOP;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.guard_nutrition_save_receipt_copy() FROM PUBLIC;
CREATE TRIGGER nutrition_save_receipt_copy BEFORE INSERT OR UPDATE ON public.command_receipt
 FOR EACH ROW EXECUTE FUNCTION public.guard_nutrition_save_receipt_copy();
